package interpreter

import (
	"context"
	"math"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/trufnetwork/kwil-db/common"
	"github.com/trufnetwork/kwil-db/core/types"
	"github.com/trufnetwork/kwil-db/node/engine"
	pggenerate "github.com/trufnetwork/kwil-db/node/engine/pg_generate"
)

// Test_PrepareQuerySQLGenerator checks that a statement is generated by the
// generator its context uses, that the statement cache keeps the form
// prepared for one context out of the others, and that a context using the
// legacy generator orders a statement as releases before the generator
// upgrade did: with default ordering only if the context that first prepared
// the statement could change state.
func Test_PrepareQuerySQLGenerator(t *testing.T) {
	pggenerate.SetUpgradeHeights(func(chainID string) int64 {
		if chainID == "test-chain" {
			return 10
		}
		return math.MaxInt64
	})
	statementCache.clear()
	t.Cleanup(func() {
		pggenerate.SetUpgradeHeights(nil)
		statementCache.clear()
	})

	interp := &baseInterpreter{
		namespaces: map[string]*namespace{
			engine.DefaultNamespace: {
				tables: map[string]*engine.Table{
					"users": {
						Name: "users",
						Columns: []*engine.Column{
							{Name: "id", DataType: types.IntType, IsPrimaryKey: true},
							{Name: "name", DataType: types.TextType, Nullable: true},
						},
					},
				},
				availableFunctions: copyBuiltinExecutables(),
			},
		},
	}

	execCtx := func(chainID string, height int64, canMutateState bool) *executionContext {
		return &executionContext{
			engineCtx: &common.EngineContext{
				TxContext: &common.TxContext{
					Ctx: context.Background(),
					BlockContext: &common.BlockContext{
						Height:       height,
						ChainContext: &common.ChainContext{ChainID: chainID},
					},
				},
			},
			scope:          newScope(engine.DefaultNamespace),
			canMutateState: canMutateState,
			interpreter:    interp,
		}
	}
	outsideBlock := execCtx("test-chain", 20, true)
	outsideBlock.engineCtx.InvalidTxCtx = true

	type step struct {
		name string
		ctx  *executionContext
		want string
	}
	run := func(stmt string, steps []step) {
		t.Helper()
		for _, step := range steps {
			got, _, args, err := step.ctx.prepareQuery(stmt)
			require.NoError(t, err, step.name)
			require.Equal(t, step.want, got, step.name)
			require.Empty(t, args, step.name)
		}
	}

	// The two generators write these statements differently: each aggregate
	// has its own ORDER BY and a literal argument with a parenthesis.
	const stmt = "SELECT array_agg(name || ' (' ORDER BY id) FROM users;"
	const (
		legacy          = "\nSELECT array_agg(name || ' (' ORDER BY name || ' (' ORDER BY id)\nFROM main.users\nORDER BY 1;"
		legacyUnordered = "\nSELECT array_agg(name || ' (' ORDER BY name || ' (' ORDER BY id)\nFROM main.users\n;"
		current         = "\nSELECT array_agg(name || ' (' ORDER BY id)\nFROM main.users\nORDER BY 1;"
		readOnly        = "\nSELECT array_agg(name || ' (' ORDER BY id)\nFROM main.users\n;"
	)

	// A read-only call prepares the statement first, so every context that
	// uses the legacy generator runs it without default ordering, as earlier
	// releases did.
	run(stmt, []step{
		{"read-only call", execCtx("", -1, false), readOnly},
		{"read-only call with a block below the upgrade height", execCtx("test-chain", 9, false), readOnly},
		{"block below the upgrade height", execCtx("test-chain", 9, true), legacyUnordered},
		{"block at the upgrade height", execCtx("test-chain", 10, true), current},
		{"block below the upgrade height again", execCtx("test-chain", 9, true), legacyUnordered},
		{"block above the upgrade height", execCtx("test-chain", 11, true), current},
		{"block on a chain with no upgrade height", execCtx("other-chain", 11, true), legacyUnordered},
		{"statement outside a block", outsideBlock, legacyUnordered},
		{"read-only call again", execCtx("", -1, false), readOnly},
	})

	// A block below the upgrade height prepares this statement first, so it
	// keeps default ordering there, while a read-only call runs its own form.
	const stmtDesc = "SELECT array_agg(name || ' (' ORDER BY id DESC) FROM users;"
	const (
		legacyDesc   = "\nSELECT array_agg(name || ' (' ORDER BY name || ' (' ORDER BY id DESC)\nFROM main.users\nORDER BY 1;"
		currentDesc  = "\nSELECT array_agg(name || ' (' ORDER BY id DESC)\nFROM main.users\nORDER BY 1;"
		readOnlyDesc = "\nSELECT array_agg(name || ' (' ORDER BY id DESC)\nFROM main.users\n;"
	)
	run(stmtDesc, []step{
		{"block below the upgrade height", execCtx("test-chain", 9, true), legacyDesc},
		{"read-only call", execCtx("", -1, false), readOnlyDesc},
		{"block below the upgrade height again", execCtx("test-chain", 9, true), legacyDesc},
		{"statement outside a block", outsideBlock, legacyDesc},
		{"block at the upgrade height", execCtx("test-chain", 10, true), currentDesc},
	})

	// A schema change clears the cache of earlier releases too, so the next
	// context to prepare the statement decides its ordering again.
	statementCache.clear()
	run(stmt, []step{
		{"block below the upgrade height after a schema change", execCtx("test-chain", 9, true), legacy},
		{"read-only call after a schema change", execCtx("", -1, false), readOnly},
		{"block below the upgrade height after the read-only call", execCtx("test-chain", 9, true), legacy},
	})
}
